local function keyname(k)
	if typeof(k) ~= "EnumItem" then
		return "None"
	end

	local n = k.Name

	if terse[n] then
		return terse[n]
	end

	local pad = string.match(n, "^Keypad(.+)$")

	if pad then
		return "Num" .. pad
	end

	return n
end

