			ZIndex = 31,
		}, sv)

		new("UICorner", { CornerRadius = UDim.new(1, 0) }, dot)
		new("UIStroke", { Color = th.bg, Transparency = 0.25 }, dot)

		local bar = new("Frame", {
			Name = rnd(),
			Active = true,
			Position = UDim2.fromOffset(10, 146),
			Size = UDim2.new(1, -20, 0, 10),
