				}, row) or nil

				if dots then
					round(dots, 6)
				end

				table.insert(seek.rows, { row = row, name = t.name })

				local item = { row = row, on = false }
				local warm = false

				if dots then
					local pod = bloom(row, t.name, vue, keep)

					item.pod = pod
					item.options = pod.api

					function item:setoptions(v)
						pod:setopen(v)
