            }, Static={
                kind="particle", sprite={"p_lightning","p_sparkle"}, size=0.9, rate=75, life=0.35, speed={2.4,5.5}, spread=75, rise=0, drag=0.8, spin=300, light=1.2
            }, Frost={
                kind="particle", sprite={"p_snowflake","p_sparkle"}, size=0.78, rate=55, life=2.4, speed={0.2,0.8}, spread=80, rise=-1, drag=5, spin=60, light=0.7
            }, Bloomburst={
                kind="particle", sprite={"p_bloom","p_glow","p_glowboost"}, size=1.1, rate=100, life=0.5, speed={3,7}, spread=180, rise=0, drag=1, spin=120, light=1.4
            }, Ribbon={kind="ribbon",texture="",light=1}, Comet={kind="ribbon",texture=Host.Asset.file(assetDir.."p_glow.png"),local_file=true,light=2}, Smoke={kind="ribbon",texture="rbxasset://textures/particles/smoke_main.dds",light=0.4}
        }, {"Bloom","Glow","Sparkle","Stars","Fireflies","Hearts","Snow","Lightning","Crowns","Smolder","Halo","Starfall","Swarm","Static","Frost","Bloomburst","Ribbon","Comet","Smoke"};
        
        local function
             assetIdOf(asset)return Host.Asset.id(asset)or"";
            
        end;
        
        local function
             textureOf(sty)if sty.sprite then
                 return assetIdOf(Host.Asset.file(assetDir..sty.sprite[math.random(1, #sty.sprite)]..".png"));
                
            end;
            if not destroyTrail.local_file then
                 return destroyTrail.texture;
                
            end;
            return assetIdOf(destroyTrail.texture);
            
        end;
        
        local active, white={}, Color3.new(1, 1, 1);
        
        local function
             destroyTrail(char)
            local rec=active[char];
            if not rec then
                 return;
                
            end;
            
            local props={"trail","emitter","a","ribbonOrColor"};
            for _, prop in ipairs(props)do
                 
                local inst=rec[prop];
                if inst then
                     pcall(function
                        ()inst:Destroy();
                        
                    end);
                    
                end;
                
            end;
            active[char]=nil;
            
        end;
        
        local function
             clearMine()for ch, rec in pairs(active)do
                 if not rec.cfg or rec.cfg==cfg then
                     destroyTrail(ch);
                    
                end;
                
            end;
            
        end;
        
        local function
             baseColors(c)c=c or cfg;
            if c.Rainbow then
                 
                local phase=os.clock()*0.12%1;
                return Color3.fromHSV(phase, 0.85, 1), Color3.fromHSV((phase+0.22)%1, 0.85, 1);
                
            end;
            return c.Color, c.Color2;
            
        end;
        
        local function
             colorSeqOf(sty, c)if sty.own then
                 return ColorSequence.new(Color3.new(1, 1, 1));
                
            end;
            
            local cA, cB=baseColors(c);
            return ColorSequence.new(cA, cB);
            
        end;
        
        local function
             emitterSize(sty, c)c=c or cfg;
            
            local k=sty.size*(c.Size/10);
            return NumberSequence.new({NumberSequenceKeypoint.new(0,k*0.35),NumberSequenceKeypoint.new(0.25,k),NumberSequenceKeypoint.new(1,k*0.1)});
            
        end;
        
        local function
             emitterFade(c)c=c or cfg;
            
            local k=1-math.clamp(c.Bright/100, 0.05, 1);
            return NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(0.12,k),NumberSequenceKeypoint.new(0.55,k+(1-k)*0.35),NumberSequenceKeypoint.new(1,1)});
            
        end;
        
        local spawnEmitter=nil;
        spawnEmitter=function
            (char, root, sty, c)c=c or cfg;
            
            local attachA=Instance.new("Attachment");
            attachA.Name=Host.Fw.RandomString();
            attachA.Position=Vector3.new(0, -0.9, 0);
            attachA.Parent=root;
            
            local em=Instance.new("ParticleEmitter");
            em.Name=Host.Fw.RandomString();
            em.Texture=textureOf(sty);
            em.LightEmission=sty.light;
            em.LightInfluence=0;
            em.Enabled=false;
            em.Rate=sty.rate*(c.Rate/100)*(c.Amount/100);
            em.Lifetime=NumberRange.new(c.Life*0.65, c.Life);
            em.Speed=NumberRange.new(sty.speed[1], sty.speed[2]);
            em.SpreadAngle=Vector2.new(sty.spread, sty.spread)*(c.Spread/100);
            em.Acceleration=Vector3.new(0, sty.rise*(c.Gravity/100), 0);
            em.Drag=sty.drag;
            em.VelocityInheritance=0.3;
            em.EmissionDirection=Enum.NormalId.Back;
            em.Rotation=NumberRange.new(0, 360);
