            em.Size=emitterSize(sty, c);
            em.Transparency=emitterFade(c);
            em.Parent=attachA;
            active[char]={emitter=em,a=attachA,root=root,style=sty,swap=0,size=c.Size,rate=c.Rate,amount=c.Amount,bright=c.Bright,enabled=false,life=c.Life,cfg=c};
            
        end;
        
        local function
             spawnRibbon(char, root, sty, c)c=c or cfg;
            
            local attachA=Instance.new("Attachment");
