            inst.LightEmission=sty.light;
            inst.LightInfluence=0;
            inst.Texture=textureOf(sty);
            inst.TextureMode=Enum.TextureMode.Static;
            inst.TextureLength=4;
            inst.Color=ColorSequence.new(cA, cB);
            inst.WidthScale=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(0.5,0.62),NumberSequenceKeypoint.new(1,0)});
            
            local f=1-math.clamp(c.Bright/100, 0.05, 1);
            inst.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,f),NumberSequenceKeypoint.new(0.7,f+(1-f)*0.5),NumberSequenceKeypoint.new(1,1)});
            inst.Parent=guestCfg;
            active[char]={trail=inst,a=attachA,ribbonOrColor=attachB,root=root,style=sty,size=c.Size,life=c.Life,first=cA,second=cB,cfg=c};
            
        end;
        
        local gfx=Host.Store.GameFX;
        
        local guestCfg={};
        
        local attachChar=nil;
        attachChar=function
            (char)
            local root=char:FindFirstChild("HumanoidRootPart");
            if not root then
                 return;
                
            end;
            destroyTrail(char);
            
            local pl=Host.Players:GetPlayerFromCharacter(char);
            
            local g=pl and guestCfg[pl]or cfg;
            if g==cfg and cfg.Game and char==Host.LocalPlayer.Character then
                 return;
                
            end;
            sty=styles[g.Style]or styles.Bloom;
            if sty.kind=="ribbon"then
                 spawnRibbon(char, root, sty, g);
                else spawnEmitter(char, root, sty, g);
                
            end;
            
        end;
        
        local function
             targetOk(player)if not cfg.On then
                 return false;
                
            end;
            
            local isSelf=player==Host.LocalPlayer;
            return cfg.Target=="All"or isSelf and cfg.Target=="Self"or not isSelf and cfg.Target=="Other";
            
        end;
        
        local function
             tuneGameFx()if not gfx then
