            local cA, cB=baseColors();
            gfx.Tune("trail", {glow=cfg.Bright/85,rate=cfg.Rate/140,size=cfg.Size/10,life=cfg.Life/0.9,amount=cfg.Amount/100,color=cfg.Tint and(ColorSequence.new(cA,cB))or nil});
            
        end;
        
        local function
             nameBlocked(nm, sub)
            local hay, blocked=(tostring(nm).." "..tostring(sub or"")):lower(), {"pride","minecraft","cubic","block","cube","dash","petal","leaves","flower","flame","bubble","ember","bloomfall","confetti","reicle","reticle","relic","soap","beam","chain"};
            for _, w in ipairs(blocked)do
                 if hay:find(w, 1, true)then
                     return false;
                    
                end;
                
            end;
            return true;
            
        end;
        
        local function
             refreshAll()clearMine();
            if cfg.Game and not nameBlocked(cfg.Game)then
                 cfg.Game=nil;
                
            end;
            if gfx then
                 gfx.SetGroup("trail", cfg.On and cfg.Game and(nameBlocked(cfg.Game))and{cfg.Game}or{});
                
            end;
            tuneGameFx();
            if not cfg.On then
                 return;
                
            end;
            if not cfg.Style and not cfg.Game then
                 return;
                
            end;
            for _, pl in ipairs(Host.Players:GetPlayers())do
                 if targetOk(pl)and pl.Character then
                     attachChar(pl.Character);
                    
                end;
                
            end;
            
        end;
        
        local tick=0;
        
        local lastSig=nil;
        Host.Fw:AddSignal(Host.Run.RenderStepped:Connect(function
            (dt)if not Host.Fw.ScreenGui.Parent then
                 return;
                
            end;
            if cfg.Game and cfg.On then
                 tick+=dt;
                if tick>0.12 then
                     tick=0;
                    
                    local cA, cB=baseColors();
                    
                    local sig=table.concat({tostring(cA),tostring(cB),cfg.Bright,cfg.Rate,cfg.Amount,cfg.Size,cfg.Life,tostring(cfg.Rainbow),tostring(cfg.Tint)}, "|");
                    if sig~=lastSig then
                         lastSig=sig;
                        tuneGameFx();
                        
                    end;
                    
                end;
                
            end;
            if not next(active)then
                 return;
                
            end;
            
            local cC, cD=baseColors();
            
            local rbSeq=cfg.Rainbow and(ColorSequence.new(cC, cD))or nil;
            for char, rec in pairs(active)do
                 
                local ocfg, rc1, rc2=rec.cfg or cfg;
                if ocfg~=cfg then
                     rc1, rc2=baseColors(ocfg);
                    rbSeq=ocfg.Rainbow and(ColorSequence.new(rc1, rc2))or nil;
                    else rc1, rc2=cC, cD;
                    
                end;
                if not rec.root or not rec.root.Parent then
                     destroyTrail(fadeVal);
                    elseif rec.emitter then
                         if not rec.emitter.Parent then
                             destroyTrail(fadeVal);
                            else 
                            local spd, hum=(rec.root.AssemblyLinearVelocity*Vector3.new(1, 0, 1)).Magnitude, char:FindFirstChildOfClass("Humanoid");
                            
                            local moving, shouldEmit=hum and hum.MoveDirection.Magnitude>0.05, hum and(hum:GetState()==Enum.HumanoidStateType.Jumping or hum:GetState()==Enum.HumanoidStateType.Freefall);
                            w=ocfg.Always or spd>7 and(moving or w);
                            sty=rec.style;
                            if rec.enabled~=shouldEmit then
                                 rec.enabled=shouldEmit;
                                rec.emitter.Enabled=shouldEmit;
                                
                            end;
                            hum, spd=nil;
                            local cE, cF; if sty.own then
                                 cE, cF=white, white;
                                else cE, cF=rc1, rc2;
                                
                            end;
                            if rec.first~=cC or rec.second~=cD then
                                 rec.first=cC;
                                rec.second=cD;
                                rec.emitter.Color=not sty.own and rbSeq or(ColorSequence.new(cE, cF));
                                
                            end;
                            if rec.life~=ocfg.Life then
                                 rec.life=ocfg.Life;
                                rec.emitter.Lifetime=NumberRange.new(ocfg.Life*0.65, ocfg.Life);
                                
                            end;
                            if rec.size~=ocfg.Size then
                                 rec.size=ocfg.Size;
                                rec.emitter.Size=emitterSize(sty, ocfg);
                                
                            end;
                            if rec.rate~=ocfg.Rate or rec.amount~=ocfg.Amount then
                                 rec.rate, rec.amount=ocfg.Rate, ocfg.Amount;
                                rec.emitter.Rate=sty.rate*(ocfg.Rate/100)*(ocfg.Amount/100);
                                
                            end;
                            if rec.bright~=ocfg.Bright then
                                 rec.bright=ocfg.Bright;
                                rec.emitter.Transparency=emitterFade(ocfg);
                                
                            end;
                            if sty.sprite and#sty.sprite>1 and shouldEmit then
                                 rec.swap=rec.swap+dt;
                                if rec.swap>0.22 then
                                     rec.swap=0;
                                    rec.emitter.Texture=textureOf(sty);
                                    
                                end;
                                
                            end;
                            
                        end;
                        elseif not rec.trail or not rec.trail.Parent then
                             destroyTrail(fadeVal);
                            else if rec.first~=rc1 or rec.second~=rc2 then
                                 rec.first=rc1;
                                rec.second=rc2;
                                rec.trail.Color=rbSeq or(ColorSequence.new(rc1, rc2));
                                
                            end;
                            if rec.life~=ocfg.Life then
                                 rec.life=ocfg.Life;
                                rec.trail.Lifetime=ocfg.Life;
                                
                            end;
                            if rec.size~=ocfg.Size then
                                 rec.size=ocfg.Size;
                                rec.a.Position=Vector3.new(0, ocfg.Size*0.09, 0);
                                rec.ribbonOrColor.Position=Vector3.new(0, -ocfg.Size*0.09, 0);
                                
                            end;
                            
                        end;
                        
                    end;
                    
                end));
                
                local function
                     hookPlayer(player)Host.Fw:AddPlayerSignal(player, player.CharacterAdded:Connect(function
                        (ch)if not targetOk(player)then
                             return;
                            
                        end;
                        task.delay(1, function
                            ()if Host.Alive()and cfg.On and(targetOk(player))and player.Parent and player.Character==ch and ch.Parent then
                                 attachChar(ch);
                                
                            end;
                            
                        end);
                        
                    end));
                    
                end;
                for _, pl in ipairs(Host.Players:GetPlayers())do
                     hookPlayer(pl);
                    
                end;
                Host.Fw:AddSignal(Host.Players.PlayerAdded:Connect(hookPlayer));
                Host.Store.Trail=cfg;
                cfg.Worn=function
                    ()if not(cfg.On and cfg.Style and styles[cfg.Style]and(cfg.Target=="Self"or cfg.Target=="All"))then
                         return nil;
                        
                    end;
                    return{s=cfg.Style,a=cfg.Color:ToHex(),b=cfg.Color2:ToHex(),r=cfg.Rainbow==true,z=cfg.Size,l=cfg.Life,n=cfg.Rate,g=cfg.Bright,m=cfg.Amount,w=cfg.Always==true};
                    
                end;
                cfg.Dress=function
                    (pl, data)if pl==Host.LocalPlayer then
                         return;
                        
                    end;
                    if type(data)~="table"or not styles[tostring(data.s)]then
                         cfg.Undress(pl);
                        return;
                        
                    end;
                    
                    local r1, v1=pcall(Color3.fromHex, tostring(data.a));
                    
                    local r2, v2=pcall(Color3.fromHex, tostring(data.b));
                    
                    local g={
                        Style=tostring(data.s), Color=r1 and v1 or cfg.Color, Color2=r2 and v2 or cfg.Color2, Rainbow=data.r==true, Size=math.clamp(tonumber(data.z)or 10, 1, 40), Life=math.clamp(tonumber(data.l)or 0.9, 0.1, 5), Rate=math.clamp(tonumber(data.n)or 140, 1, 600), Bright=math.clamp(tonumber(data.g)or 85, 1, 100), Amount=math.clamp(tonumber(data.m)or 100, 1, 400), Spread=100, Gravity=100, Always=data.w==true
                    };
                    g.key=table.concat({g.Style,tostring(data.a),tostring(data.b),tostring(g.Rainbow),g.Size,g.Life,g.Rate,g.Bright,g.Amount,tostring(g.Always)}, "|");
                    if guestCfg[pl]and guestCfg[pl].key==g.key then
                         return;
                        
                    end;
                    guestCfg[pl]=g;
                    if pl.Character then
                         pcall(attachChar, pl.Character);
                        
                    end;
                    
                end;
                cfg.Undress=function
                    (pl)if not guestCfg[pl]then
                         return;
                        
                    end;
                    guestCfg[pl]=nil;
                    
                    local ch=pl.Character;
                    if ch and active[ch]and active[ch].cfg~=cfg then
                         destroyTrail(ch);
                        
                    end;
                    if ch and cfg.On and(targetOk(pl))then
                         pcall(attachChar, ch);
                        
                    end;
                    
                end;
                cfg.Guests=function
                    ()return guestCfg;
                    
                end;
                task.spawn(function
                    ()while Host.Alive()do
                         task.wait(1);
                        for pl, g in pairs(guestCfg)do
                             if not pl.Parent then
                                 guestCfg[pl]=nil;
                                else 
                                local ch=pl.Character;
                                
                                local rec=ch and active[ch];
                                if ch and(ch:FindFirstChild("HumanoidRootPart"))and not(rec and rec.cfg==g)then
                                     pcall(attachChar, ch);
                                    
                                end;
                                
                            end;
                            
                        end;
                        
                    end;
                    
                end);
                Host.Store.TrailStyles=styleNames;
                Host.Store.ClearTrail=function
                    ()cfg.On=false;
