            local function
                 buildSlot(tex)
                local bm=Instance.new("Beam");
                bm.Attachment0=attA;
                bm.Attachment1=attB;
                bm.FaceCamera=true;
                bm.LightInfluence=0;
                bm.LightEmission=1;
                bm.Texture=tex;
                bm.TextureSpeed=0;
                bm.Segments=8;
                bm.Width0, bm.Enabled, bm.Parent=0, false, part;
                return bm;
                
            end;
            
            local card=Instance.new("BillboardGui");
            card.Adornee, card.AlwaysOnTop=attB, y.ThroughWalls;
            card.LightInfluence=0;
            card.Size, card.Enabled, card.Parent=UDim2.fromScale(1, 1), false, part;
            
            local img=Instance.new("ImageLabel");
            img.BackgroundTransparency, img.Size=1, UDim2.fromScale(1, 1);
            img.Image=texHaze;
            img.Parent=card;
            
            local star=Instance.new("ImageLabel");
            star.BackgroundTransparency, star.Size=1, UDim2.fromScale(0.85, 0.85);
            star.AnchorPoint, star.Position=Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5);
            star.Image=texStar;
            star.Rotation=15;
            star.Parent=card;
            return{tail=attA,nose=attB,line=buildSlot(texLine),haze=buildSlot(texHaze),card=card,blob=img,star=star,busy=false};
            
        end;
        
        local function
             release(s)s.busy, s.line.Enabled, s.haze.Enabled, s.card.Enabled=false, false, false, false;
            
        end;
        
        local function
             spawn(cam0)
            local maxN, busy, s=math.floor(worldFx.Number(y.Count, 20, 1, maxStars)), 0;
            for _, m in ipairs(slots)do
                 if m.busy then
                     busy+=1;
                    else s=if not s then
                         m else s;
                        
                    end;
                    
                end;
                if not s or busy>=maxN then
                     return false;
                    
                end;
                preset, look=showerDefs[y.Preset]or showerDefs.Perseids, cam0.CFrame.LookVector;
                
                local ang, dist=math.atan2(look.Z, look.X)+rng:NextNumber(-1.45, 1.45), y.Distance*rng:NextNumber(0.7, 1.2);
                s.origin=cam0.CFrame.Position+Vector3.new(math.cos(ang)*dist, dist*rng:NextNumber(0.5, 1), math.sin(ang)*dist);
                vel=Vector3.new(rng:NextNumber(-preset.spread, preset.spread), rng:NextNumber(-0.06, 0.06), rng:NextNumber(-preset.spread, preset.spread));
                s.velocity=(preset.direction+vel).Unit*preset.speed*rng:NextNumber(0.85, 1.15);
                s.fire=y.Fireballs and rng:NextNumber()<0.07;
                s.mass=s.fire and(rng:NextNumber(1.7, 2.2))or(rng:NextNumber(0.45, 1.1));
                s.life=y.Life*rng:NextNumber(0.85, 1.15)*(s.fire and 1.2 or 1);
                s.age=0;
                s.travel=0;
                s.busy=true;
                return true;
                
            end;
            
            local function
                 tick(dt)if not Host.Alive()or not y.On or not part or not part.Parent then
                     return;
                    
                end;
                
                local cam=Host.Fx.camera();
                if not cam then
                     return;
                    
                end;
                dt=math.clamp(dt, 0, 0.1);
                
                local camPos=cam.CFrame.Position;
                if lastPos and(camPos-lastPos).Magnitude>y.Distance*2 then
                     for _, m in ipairs(slots)do
                         release(m);
                        
                    end;
                    timer=0;
                    
                end;
                lastPos=camPos;
                
                local maxN=math.floor(worldFx.Number(y.Count, 20, 1, maxStars));
                for i=1, math.min(3, maxN-#slots), 1 do
                     slots[#slots+1]=makeSlot();
                    
                end;
                y.Allocated=#slots;
                if headCol~=y.Head or tailCol~=y.Tail then
                     headCol, tailCol, seq=y.Head, y.Tail, ColorSequence.new(y.Tail, y.Head);
                    
                end;
                timer-=dt;
                if timer<=0 then
                     spawn(cam);
                    timer=60/y.Rate*rng:NextNumber(0.8, 1.2);
                    
                end;
                catimer=0;
                for _, m in ipairs(slots)do
                     if m.busy then
                         busy+=1;
                        if busy>maxN then
                             release(m);
                            busy-=1;
                            else m.age=m.age+dt;
                            m.travel=m.travel+dt*y.Speed/100;
                            pos=worldFx.MeteorPoint(m.origin, m.velocity, m.travel);
                            
                            local fade=worldFx.Smooth((pos.Y-camPos.Y-10)/40);
                            if m.age>=m.life or fade<=0 then
                                 release(m);
                                busy-=1;
                                else 
                                local bright, len=worldFx.Envelope(m.age, m.life, 0.1, 0.32)*fade, math.min(m.travel*m.velocity.Magnitude, (30+m.mass*22)*y.Length/100);
                                
                                local back=m.travel-len/m.velocity.Magnitude;
                                backPos=worldFx.MeteorPoint(m.origin, m.velocity, back);
                                m.nose.WorldCFrame=worldFx.Frame(pos, m.velocity+Vector3.new(0, -3.6*m.travel, 0));
                                m.tail.WorldCFrame=worldFx.Frame(backPos, m.velocity+Vector3.new(0, -3.6*back, 0));
                                
                                local level, wdt, curve=math.floor(math.clamp(bright, 0, 1)*levels+0.5), 0.55*m.mass*y.Size/100, (pos-backPos).Magnitude/3;
                                if m.colors~=seq then
                                     m.line.Color, m.haze.Color, m.blob.ImageColor3=seq, seq, y.Head;
                                    m.star.ImageColor3=y.Head;
                                    m.colors=seq;
                                    
                                end;
                                if m.level~=level then
                                     m.line.Transparency, m.haze.Transparency=lineFades[level], hazeFades[level];
                                    m.level=level;
                                    
                                end;
                                m.line.Width1, m.haze.Width1=wdt, wdt*3.4;
                                m.line.CurveSize0, m.line.CurveSize1=curve, curve;
                                m.haze.CurveSize0, m.haze.CurveSize1=curve, curve;
                                m.line.Enabled, m.haze.Enabled, m.card.Enabled=bright>0.005, bright>0.005, bright>0.005;
                                Host.Fx.FxDepth(m.line, y.ThroughWalls);
                                Host.Fx.FxDepth(m.haze, y.ThroughWalls);
                                m.card.AlwaysOnTop=y.ThroughWalls;
                                sz=y.HeadSize*(m.fire and 1.35 or 1);
                                m.card.Size=UDim2.fromOffset(sz, sz);
                                m.blob.ImageTransparency=1-bright*(y.Stars and 0.35 or(m.fire and 0.9 or 0.72));
                                m.star.ImageTransparency=y.Stars and 1-bright*0.95 or 1;
                                
                            end;
                            
                        end;
                        
                    end;
                    
                end;
                y.Active=busy;
                
            end;
            
            local function
                 stop()rev+=1;
                starting, lastPos, timer=false, nil, 0;
                if conn then
                     conn:Disconnect();
                    conn=nil;
                    
                end;
                for _, m in ipairs(slots)do
                     release(m);
                    
                end;
                y.Active=0;
                
            end;
            
            local function
                 start()if conn or starting or not Host.Alive()or not y.On then
                     return;
                    
                end;
                starting=true;
                
                local rev2=rev;
                
                local ok, res=pcall(ensure, rev2);
                if rev2~=rev then
                     return;
                    
                end;
                starting=false;
                if not ok then
                     stop();
                    warn("[visuals] Starfall: "..tostring(res));
                    return;
                    
                end;
                if not res or not Host.Alive()or not y.On then
                     return;
                    
                end;
                timer=0;
                conn=Host.Run.RenderStepped:Connect(tick);
                
            end;
            
            local starLabel=Host.UI.Starfall:AddLabel("Starfall");
            starLabel:AddToggle({
                Default=false, Flag="starfall", Callback=function
                    (v)y.On=v==true;
                    if y.On then
                         start();
                        else stop();
                        
                    end;
                    
                end
            });
            starLabel:AddColorPicker({
                Default=y.Head, Flag="starfall_head", Callback=function
                    (v)y.Head=v;
                    
                end
            });
            Host.UI.Starfall:AddLabel("Shower Preset"):AddDropdown({
                Default="Perseids", Values=presetNames, Flag="starfall_preset", Callback=function
                    (v)y.Preset=table.find(presetNames, v)and v or"Perseids";
                    
                end
            });
            Host.UI.Starfall:AddLabel("Max Stars"):AddSlider({
                Min=1, Max=maxStars, Default=20, Rounding=0, Size=100, Flag="starfall_count", Callback=function
                    (v)y.Count=worldFx.Number(v, 20, 1, maxStars);
                    
                end
            });
            Host.UI.Starfall:AddLabel("Spawn Rate"):AddSlider({
                Min=2, Max=600, Default=150, Rounding=0, Type="/min", Size=100, Flag="starfall_rate", Callback=function
                    (v)y.Rate=worldFx.Number(v, 150, 2, 600);
                    timer=0;
                    
                end
            });
            
            local optGrp=starLabel:AddOption(1);
            optGrp:AddLabel("Tail Color"):AddColorPicker({
                Default=y.Tail, Flag="starfall_tail", Callback=function
                    (v)y.Tail=v;
                    
                end
            });
            sliderDefs={
                {
                    "Travel Speed", "starfall_speed", 20, 250, 100, "%", function
                        (v)y.Speed=worldFx.Number(v, 100, 20, 250);
                        
                    end
                }, {
                    "Tail Length", "starfall_length", 20, 260, 100, "%", function
                        (v)y.Length=worldFx.Number(v, 100, 20, 260);
                        
                    end
                }, {
                    "Size", "starfall_size", 20, 250, 100, "%", function
                        (v)y.Size=worldFx.Number(v, 100, 20, 250);
                        
                    end
                }, {
                    "Lifetime", "starfall_life", 1, 12, 4, "s", function
                        (v)y.Life=worldFx.Number(v, 4, 1, 12);
                        
                    end
                }, {
                    "Sky Distance", "starfall_distance", 100, 500, 260, "", function
                        (v)y.Distance=worldFx.Number(v, 260, 100, 500);
                        
                    end
                }
            };
            for _, def in ipairs(sliderDefs)do
                 optGrp:AddLabel(def[1]):AddSlider({Min=def[3],Max=def[4],Default=def[5],Type=def[6],Rounding=0,Size=100,Flag=def[2],Callback=def[7]});
                
            end;
            optGrp:AddLabel("Bright Meteors"):AddToggle({
                Default=true, Flag="starfall_fireballs", Callback=function
                    (v)y.Fireballs=v;
                    
                end
            });
            optGrp:AddLabel("Star Heads"):AddToggle({
                Default=true, Flag="starfall_stars", Callback=function
                    (v)y.Stars=v;
                    
                end
            });
            optGrp:AddLabel("Head Size"):AddSlider({
                Min=3, Max=64, Default=14, Rounding=0, Type="px", Size=100, Flag="starfall_head_size", Callback=function
                    (v)y.HeadSize=worldFx.Number(v, 14, 3, 64);
                    
                end
            });
            Host.Fw.ClearStarfall=Host.OnUnload("starfall", function
                ()y.On=false;
                stop();
                if part then
                     part:Destroy();
                    part=nil;
                    
                end;
                table.clear(slots);
                y.Allocated=0;
                
            end);
            
end

return initStarfall

end)()

-- ----- pilot: bloom -----
local initBloom = (function()
-- Bloom / Glyphs (SaladVisuals) — bezier light-trail sparks projected to screen (Line pool + glow dots).
--
-- HOST CONTRACT: call initBloom(Host) once. Host fields used:
--   Host.Fx.pool("Line", hideCb) -> linePool, dotHolder, dots, dotCount, tex
--   Host.Fx.camera() -> cam; Host.Fx.basis() -> frame {pos}; Host.Fx.project(frame, vec3) -> x, y, front
--   Host.Asset.id(asset); Host.Asset.file(path)
--   Host.Alive() -> bool
--   Host.Fw.AccentColor (optional); Host.Fw:AddSignal(conn); Host.Fw.ScreenGui
--   Host.Run.RenderStepped
--   Host.App.WindowFrame() -> frame or nil; Host.App.Glyphs / Host.App.ClearGlyphs (set by feature)
--   Host.Preview.Panel (optional, may be nil)
--   Host.OnUnload(name, fn)
--   Host.UI.Glyphs                            config page: AddLabel/AddToggle/AddColorPicker/AddDropdown/AddSlider
-- NOTE: themeColor() uses a local accumulator (original clobbered the shared turn-rate
-- constant as a side effect; preserved behavior would break spark turning, so scoped).
local function initBloom(Host)
        local cfg={On=false,Count=55,Mode="Theme",Color=Color3.fromRGB(120,200,255),Speed=16,Length=34,Width=2,Life=7,Glow=true};
        
        local rng=Random.new(93882);
        
        local sparks={};
        
        local axes={Vector3.new(1,0,0),Vector3.new(-1,0,0),Vector3.new(0,1,0),Vector3.new(0,-1,0),Vector3.new(0,0,1),Vector3.new(0,0,-1)};
        
        local maxDist=120;
        
        local fadeInK=0.7;
        
        local fadeOutK=1.4;
        
        local turnRate=0.22;
        
        local distList={14,24,36,50,66,84};
        
        local slotIdx=0;
        
        local stepInit=2.39996323;
        
        local seed=0;
        
        local linePool, dotHolder, dots, dotCount, tex=Host.Fx.pool("Line", function
            (d)d.Visible=false;
            
        end), Host.Fx.gui("glyphdots", -3), {}, 0;
        task.spawn(function
            ()
            local ok, tex2=pcall(function
                ()return Host.Asset.id(Host.Asset.file("particles/p_bloom.png"));
                
            end);
            
            local ensured=Host.Alive()and ok;
            if ensured then
                 tex=tex2;
                
            end;
            
        end);
        
        local function
             getDot()if not tex or dotCount>=420 then
                 return nil;
                
            end;
            dotCount+=1;
            
            local d=dots[dotCount];
            if not d then
                 d=Instance.new("ImageLabel");
                d.Name="Bloom";
                d.AnchorPoint=Vector2.new(0.5, 0.5);
                d.BackgroundTransparency=1;
                d.BorderSizePixel=0;
                d.Image=tex;
                d.ResampleMode=Enum.ResamplerMode.Default;
                d.Visible=false;
                d.Parent=dotHolder;
                dots[dotCount]=d;
                
            end;
            return d;
            
        end;
        
        local function
             hideExtra()linePool.done();
            for i=dotCount+1, #dots, 1 do
                 if dots[i].Visible then
                     dots[i].Visible=false;
                    
                end;
                
            end;
            
        end;
        
        local conn;
        
        local function
             teardown()if conn then
                 pcall(function
                    ()conn:Disconnect();
                    
                end);
                conn=nil;
                
            end;
            linePool.wipe();
            for _, d in ipairs(dots)do
                 pcall(function
                    ()d:Destroy();
                    
                end);
                
            end;
            table.clear(dots);
            table.clear(sparks);
            dotCount=0;
            
        end;
        
        local function
             spawn(staggered)
            local cam=Host.Fx.camera();
            if not cam then
                 return nil;
                
            end;
            
            local cf=cam.CFrame;
            slotIdx=slotIdx%#distList+1;
            seed+=stepInit;
            dist=distList[slotIdx]*rng:NextNumber(0.85, 1.15);
            
            local inner=dist*0.7;
            
            local rad=math.sqrt(rng:NextNumber(0.05, 1))*inner;
            
            local pos, dir, life=cf.Position+cf.LookVector*dist+cf.RightVector*math.cos(seed)*rad+cf.UpVector*math.sin(seed)*rad*0.6, axes[rng:NextInteger(1, 6)], cfg.Life*rng:NextNumber(0.7, 1.35);
            return{
                pts={pos}, sx={}, sy={}, son={}, sfar={}, head=pos, dir=dir, goal=dir, turn=1, run=0, leg=rng:NextNumber(3, 9), life=life, age=staggered and(rng:NextNumber(0, life*0.8))or 0, phase=rng:NextNumber(0, 1)
            };
            
        end;
        
        local function
             stepSpark(sp, dt)sp.age=sp.age+dt;
            if sp.turn<1 then
                 sp.turn=math.min(1, sp.turn+dt/turnRate);
                
                local k=sp.turn*sp.turn*(3-2*sp.turn);
                
                local nd=sp.dir:Lerp(sp.goal, k);
                if nd.Magnitude>0.001 then
                     sp.dir=nd.Unit;
                    
                end;
                
            end;
            
            local step=cfg.Speed*dt;
            sp.head=sp.head+sp.dir*step;
            sp.run=sp.run+step;
            if sp.run>=sp.leg then
                 sp.pts[#sp.pts+1]=sp.head;
                sp.goal=axes[rng:NextInteger(1, 6)];
                sp.turn=0;
                sp.run=0;
                sp.leg=rng:NextNumber(3, 9);
                
            end;
            total=(sp.head-sp.pts[#sp.pts]).Magnitude;
            for i=2, #sp.pts, 1 do
                 total+=(sp.pts[i]-sp.pts[i-1]).Magnitude;
                
            end;
            over=total-cfg.Length;
            while over>0 and#sp.pts>=2 do
                 seg=sp.pts[2]-sp.pts[1];
                
                local segLen=seg.Magnitude;
                if segLen<=over then
                     table.remove(sp.pts, 1);
                    over-=segLen;
                    else sp.pts[1]=sp.pts[1]+seg.Unit*over;
                    over=0;
                    
                end;
                
            end;
            if over>0 and#sp.pts==1 then
                 seg=sp.head-sp.pts[1];
                if seg.Magnitude>over then
                     sp.pts[1]=sp.pts[1]+seg.Unit*over;
                    
                end;
                
            end;
            
        end;
        
        local function
             fadeOf(sp, dist)if sp.age>=sp.life then
                 return 0;
                
            end;
            
            local a, left=math.min(1, sp.age/fadeInK), sp.life-sp.age;
            a=if left<fadeOutK then
                (math.min(a, left/fadeOutK))else a;
                d=(sp.head-dist).Magnitude;
                if d>maxDist then
                     return 0;
                    
                end;
                return if d>maxDist*0.75 then
                     a*(1-(d-maxDist*0.75)/(maxDist*0.25))else a;
                    
                end;
                
                local themeColor=nil;
                themeColor=function
                    (spark, frame, t)if cfg.Mode=="Rainbow"then
                         return Color3.fromHSV((t*0.11+spark.phase)%1, 0.85, 1);
                        
                    end;
                    if cfg.Mode=="Single"then
                         return cfg.Color;
                        
                    end;
                    
                    local h, sv, vv=(Host.Fw.AccentColor or cfg.Color):ToHSV();
                    local k=math.sin(frame*0.5+spark.phase*6.283)*0.09;
                    return Color3.fromHSV((h+k)%1, math.clamp(sv, 0.35, 1), math.max(vv, 0.65));
                    
                end;
                
                local fadeIn, fadeOut;
                
                local function
                     boundsUnion(view, pad)if not(view and view.Visible and view.AbsoluteSize.X>8)then
                         return;
                        
                    end;
                    
                    local lo, hi=view.AbsolutePosition-Vector2.new(10, pad), view.AbsolutePosition+view.AbsoluteSize+Vector2.new(10, 10);
                    fadeIn=fadeIn and(Vector2.new(math.min(fadeIn.X, lo.X), math.min(fadeIn.Y, lo.Y)))or lo;
                    fadeOut=fadeOut and(Vector2.new(math.max(fadeOut.X, hi.X), math.max(fadeOut.Y, hi.Y)))or hi;
                    
                end;
                
                local function
                     clipSeg(e0, e1, e2, e3)if not fadeIn then
                         return false;
                        
                    end;
                    
                    local dx, dy, t0, t1=e2-e0, e3-e1, 1, 0;
                    for i=1, 4, 1 do
                         t, u=nil;
                        if i==1 then
                             t, u=-dx, e0-fadeIn.X;
                            elseif i==2 then
                                 t, u=dx, fadeOut.X-e0;
                                elseif i==3 then
                                     t, u=-dy, e1-fadeIn.Y;
                                    else t, u=dy, fadeOut.Y-e1;
                                    
                                end;
                                if t==0 then
                                     if u<0 then
                                         return false;
                                        
                                    end;
                                    else i=u/t;
                                    if t<0 then
                                         if i>t0 then
                                             return false;
                                            
                                        end;
                                        t1=if i>t1 then
                                             i else t1;
                                            else if i<t1 then
                                                 return false;
                                                
                                            end;
                                            t0=if i<t0 then
                                                 i else t0;
                                                
                                            end;
                                            
                                        end;
                                        
                                    end;
                                    return true;
                                    
                                end;
                                
                                local function
                                     drawSeg(a, b, col, w, alpha)if cfg.Glow then
                                         
                                        local ln=linePool.take();
                                        ln.From=a;
                                        ln.To=b;
                                        ln.Color=col;
                                        ln.Thickness=math.max(1, w*3.2);
                                        ln.Transparency=alpha*0.16;
                                        ln.Visible=true;
                                        
                                    end;
                                    
                                    local ln=linePool.take();
                                    ln.From=a;
                                    ln.To=b;
                                    ln.Color=col;
                                    ln.Thickness=math.max(1, w);
                                    ln.Transparency=alpha;
                                    ln.Visible=true;
                                    
                                end;
                                
                                local running=true;
                                conn=Host.Fw:AddSignal(Host.Run.RenderStepped:Connect(function
                                    (dt)if not Host.Fw.ScreenGui.Parent then
                                         return;
                                        
                                    end;
                                    if not cfg.On then
                                         if running then
                                             running=false;
                                            linePool.reset();
                                            dotCount=0;
                                            if#sparks>0 then
                                                 table.clear(sparks);
                                                
                                            end;
                                            hideExtra();
                                            
                                        end;
                                        return;
                                        
                                    end;
                                    running=true;
                                    linePool.reset();
                                    dotCount=0;
                                    
                                    local frame=Host.Fx.basis();
                                    if not frame then
                                         hideExtra();
                                        return;
                                        
                                    end;
                                    dt=math.min(dt, 0.1);
                                    
                                    local fpos=frame.pos;
                                    for i=#sparks, 1, -1 do
                                         
                                        local sp=sparks[i];
                                        stepSpark(sp, dt);
                                        if sp.age>=sp.life or(sp.head-fpos).Magnitude>maxDist*1.3 then
                                             table.remove(sparks, i);
                                            
                                        end;
                                        
                                    end;
                                    budget=3;
                                    while#sparks<cfg.Count and budget>0 do
                                         budget-=1;
                                        
                                        local sp2=spawn(#sparks<cfg.Count*0.5);
                                        if not sp2 then
                                             break;
                                            
                                        end;
                                        sparks[#sparks+1]=sp2;
                                        
                                    end;
                                    fadeIn, fadeOut=nil, nil;
                                    boundsUnion(Host.App.WindowFrame and(Host.App.WindowFrame()), 42);
                                    boundsUnion(Host.Preview and Host.Preview.Panel, 10);
                                    now=os.clock();
                                    for si, sp in ipairs(sparks)do
                                         
                                        local alpha=fadeOf(sp, fpos);
                                        if alpha>0.02 then
                                             
                                            local pts=sp.pts;
                                            
                                            local segCount, col, xs, ys, vs, ds=#pts, themeColor(sp, si), sp.sx, sp.sy, sp.son, sp.sfar;
                                            for i=1, segCount, 1 do
                                                 
                                                local px, py, front=Host.Fx.project(frame, pts[i]);
                                                xs[i], ys[i], vs[i]=px, py, front>0;
                                                ds[i]=front;
                                                
                                            end;
                                            
                                            local hx, hy, hd=Host.Fx.project(frame, sp.head);
                                            segN=segCount+1;
                                            xs[segN], ys[segN], vs[segN]=hx, hy, hd>0;
                                            ds[segN]=hd;
                                            for i=2, segN, 1 do
                                                 if vs[i-1]and vs[i]then
                                                     
