--   Host.Run.RenderStepped
--   Host.Registry                            table: item -> kind ("Line"/"Square"/"Image"/"Triangle"/"Quad").
--                                              register shapes here; hidden ones get Visible=false.
local function initShapes(Host)
        local function
             insidePt(p, x0, y0, x1, y1)return p.X>=x0 and p.X<=x1 and p.Y>=y0 and p.Y<=y1;
            
        end;
        
        local function
             testShape(item, kind, x0, y0, x1, y1)if kind=="Line"then
                 
                local a, b=item.From, item.To;
                return insidePt(a, x0, y0, x1, y1)or(insidePt(b, x0, y0, x1, y1))or(insidePt((a+b)/2, x0, y0, x1, y1));
                elseif kind=="Square"or kind=="Image"then
                     
                    local pos, sz=item.Position, item.Size;
                    return pos.X<x1 and pos.X+sz.X>x0 and pos.Y<y1 and pos.Y+sz.Y>y0;
                    elseif kind=="Triangle"then
                         return insidePt(item.PointA, x0, y0, x1, y1)or(insidePt(item.PointB, x0, y0, x1, y1))or(insidePt(item.PointC, x0, y0, x1, y1));
                        elseif kind=="Quad"then
                             return insidePt(item.PointA, x0, y0, x1, y1)or(insidePt(item.PointC, x0, y0, x1, y1));
                            
                        end;
                        return insidePt(item.Position, x0, y0, x1, y1);
                        
                    end;
                    Host.Fw:AddSignal(Host.Run.RenderStepped:Connect(function
                        ()
                        local win=Host.Fw.WindowFrame;
                        if type(win)=="function" then
                            win=nil;
                        end;
                        if not(win and win.Parent and win.Visible and Host.Fw.Lib.shown)then
                             return;
                            
                        end;
                        
                        local org, sz=win.AbsolutePosition-Host.Fw.ScreenGui.AbsolutePosition, win.AbsoluteSize;
                        
                        local x0=org.X;
                        
                        local y0=org.Y;
                        
                        local x1=org.X+sz.X;
                        
                        local y1=org.Y+sz.Y;
                        for item, kind in pairs(Host.Registry)do
                             if item.Visible then
                                 ok, inside=pcall(testShape, item, kind, x0, y0, x1, y1);
                                if ok and inside then
                                     item.Visible=false;
                                    
                                end;
                                
                            end;
                            
                        end;
                        
                    end));
                    
end

return initShapes

