, Aludra=Color3.fromRGB(190, 212, 255), ["Pi Sco"]=Color3.fromRGB(190, 212, 255), Mintaka=Color3.fromRGB(188, 210, 255), Alnitak=Color3.fromRGB(188, 210, 255), Graffias=Color3.fromRGB(188, 210, 255), ["Tau Sco"]=Color3.fromRGB(188, 210, 255), Alnilam=Color3.fromRGB(186, 209, 255), Mirzam=Color3.fromRGB(186, 209, 255), Dschubba=Color3.fromRGB(186, 209, 255), Shaula=Color3.fromRGB(184, 208, 255), Adhara=Color3.fromRGB(182, 207, 255)
