        };
        for _, name in ipairs(orderedNames)do
             cfg.Picked[name]=true;
            
        end;
        Host.Store.Constellations=cfg;
        
        local function
             starVec(raH, decD)
            local ra, dec=math.rad(raH*15), math.rad(decD);
            local cosDec=math.cos(dec);
            return Vector3.new(cosDec*math.cos(ra), math.sin(dec), cosDec*math.sin(ra));
            
        end;
        
        local centers={};
        for cname, entry in pairs(destroyConstellation)do
             
            local sum=(Vector3.new(0.0, 0.0, 0.0));
            for _, star in ipairs(entry.stars)do
                 sum+=starVec(star[2], star[3]);
                
            end;
            centers[cname]=sum.Magnitude>0.001 and sum.Unit or(Vector3.new(0.0, 1.0, 0.0));
            
        end;
        
        local skyAnchor=Instance.new("Part");
        skyAnchor.Name=Host.Fw.RandomString();
        skyAnchor.Anchored=true;
        skyAnchor.CanCollide=false;
        skyAnchor.CanQuery=false;
        skyAnchor.CanTouch=false;
        skyAnchor.Transparency=1;
        skyAnchor.Size=Vector3.new(1.0, 1.0, 1.0);
        skyAnchor.Locked=true;
        skyAnchor:SetAttribute(Host.TagKey, Host.TagVal);
        skyAnchor.Parent=workspace;
        
        local starFolder=Instance.new("Folder");
        starFolder.Name=Host.Fw.RandomString();
        starFolder.Parent=skyAnchor;
        
        local glowTexture=nil;
        glowTexture=Host.Asset.asset("particles/p_glow.png");
        
        local builtMap, spin, tiltA, tiltB, curR, rscale, lighting={}, 0, 0.767944870877505, 0.4886921905584123, skyRadius, 1, game:GetService("Lighting");
        
        local function
             calcAtmoCap()
            local atmo=lighting:FindFirstChildOfClass("Atmosphere");
            
            local density=atmo and atmo.Density or 0;
            if density<=0.01 then
                 return skyRadius;
                
            end;
            return math.floor(math.clamp(atmoMax*(1-density), 24, atmoMax)/2)*2;
            
        end;
        
        local function
             calcHorizon(x)return math.clamp((x+0.03)/0.16, 0, 1);
            
        end;
        
        local spreadLim=0.05235987755982989;
        
        local function
             buildConstellation(name)
            local entry=destroyConstellation[name];
            if not entry then
                 return nil;
                
            end;
            
            local built, dirs, sum={
                stars={}, beams={}, born=os.clock(), sway=math.random()*3.141592653589793*2
            }, {}, (Vector3.new(0.0, 0.0, 0.0));
            for si, star in ipairs(entry.stars)do
                 
                local dir=starVec(star[2], star[3]);
                dirs[si]=dir;
                sum+=dir;
                
            end;
            
            local center, maxAng=#dirs>0 and sum.Magnitude>0.001 and sum.Unit or(Vector3.new(0.0, 1.0, 0.0)), 0;
            for _, d in ipairs(dirs)do
                 maxAng=(math.max(maxAng, math.acos(math.clamp(center:Dot(d), -1, 1))));
                
            end;
            
            local shrink=maxAng>spreadLim and spreadLim/maxAng or 1;
            
            local function
                 slerpDir(dir)if shrink>=0.9999 then
                     return dir;
                    
                end;
                
                local ang=math.acos(math.clamp(center:Dot(dir), -1, 1));
                if ang<1.0E-5 then
                     return center;
                    
                end;
                
                local sinA=math.sin(ang);
                return(center*(math.sin((1-shrink)*ang)/sinA)+dir*(math.sin(shrink*ang)/sinA)).Unit;
                
            end;
            sum=(Vector3.new(0.0, 0.0, 0.0));
            for si, star in ipairs(entry.stars)do
                 
                local dir, anchor=slerpDir(dirs[si]), Instance.new("Attachment");
                anchor.Name=Host.Fw.RandomString();
                anchor.Position=dir*curR;
                anchor.Parent=skyAnchor;
                
                local weight, gui=math.clamp((5.2-star[4])/6.2, 0.3, 1), Instance.new("BillboardGui");
                gui.Name=Host.Fw.RandomString();
                gui.Adornee=anchor;
                gui.AlwaysOnTop=false;
                gui.LightInfluence=0;
                gui.Size=UDim2.fromScale(1, 1);
                gui.Parent=starFolder;
                local halo=Instance.new("ImageLabel");
                halo.BackgroundTransparency=1;
                halo.AnchorPoint=Vector2.new(0.5, 0.5);
                halo.Position=UDim2.fromScale(0.5, 0.5);
                halo.Size=UDim2.fromScale(2.4, 2.4);
                halo.Image=glowTexture or"rbxasset://textures/particles/sparkles_main.dds";
                halo.Parent=gui;
                
                local dotImg=Instance.new("ImageLabel");
                dotImg.BackgroundTransparency=1;
                dotImg.AnchorPoint=Vector2.new(0.5, 0.5);
                dotImg.Position=UDim2.fromScale(0.5, 0.5);
                dotImg.Size=UDim2.fromScale(1, 1);
                dotImg.Image=glowTexture or"rbxasset://textures/particles/sparkles_main.dds";
                dotImg.Parent=gui;
                
                local nameLabel;
                if star[1]then
                     nameLabel=Instance.new("TextLabel");
                    nameLabel.AnchorPoint=Vector2.new(0.5, 0);
                    nameLabel.Position=UDim2.fromScale(0.5, 1);
                    nameLabel.Size=UDim2.fromScale(4, 0.5);
                    nameLabel.BackgroundTransparency=1;
                    nameLabel.Font=Enum.Font.Gotham;
                    nameLabel.Text=star[1];
                    nameLabel.TextSize=11;
                    nameLabel.TextTransparency=0.35;
                    nameLabel.Visible=false;
                    nameLabel.Parent=gui;
                    
                end;
                sum+=dir;
                built.stars[si]={anchor=anchor,board=gui,dot=dotImg,halo=halo,label=nameLabel,weight=weight,aim=dir,home=dir*curR,tint=tintMap[star[1]]or defaultTint,phase=math.random()*3.141592653589793*2,rate=0.5+math.random()*1.3,delay=0.04*si,alpha=0};
                
            end;
            if#entry.stars>0 then
                 local center=sum/#entry.stars;
                center=center.Magnitude>0.001 and center.Unit or(Vector3.new(0.0, 1.0, 0.0));
                local titleAnchor=Instance.new("Attachment");
                titleAnchor.Name=Host.Fw.RandomString();
                titleAnchor.Position=center*curR;
                titleAnchor.Parent=skyAnchor;
                
                local titleGui=Instance.new("BillboardGui");
                titleGui.Name=Host.Fw.RandomString();
                titleGui.Adornee=titleAnchor;
                titleGui.AlwaysOnTop=false;
                titleGui.LightInfluence=0;
                titleGui.Size=UDim2.fromScale(1, 1);
                titleGui.Enabled=false;
                titleGui.Parent=starFolder;
                
                local titleLabel=Instance.new("TextLabel");
                titleLabel.BackgroundTransparency=1;
                titleLabel.Size=UDim2.fromScale(1, 1);
                titleLabel.Font=Enum.Font.Gotham;
                titleLabel.Text=name;
                titleLabel.TextScaled=true;
                titleLabel.TextTransparency=0.45;
                titleLabel.Parent=titleGui;
                built.title={seat=titleAnchor,board=titleGui,tag=titleLabel,aim=center};
                
            end;
            for li, pair in ipairs(entry.lines)do
                 local sa, sb=built.stars[pair[1]], built.stars[pair[2]];
                if sa and sb then
                     local beam=Instance.new("Beam");
                    beam.Attachment0=sa.anchor;
                    beam.Attachment1=sb.anchor;
                    beam.FaceCamera=true;
                    beam.LightInfluence=0;
                    beam.LightEmission=1;
                    beam.Segments=1;
                    beam.Width0=4;
                    beam.Width1=4;
                    beam.Parent=skyAnchor;
                    built.beams[#built.beams+1]={beam=beam,a=sa,b=sb,delay=0.45+0.05*li,shown=-1};
                    
                end;
                
            end;
            return built;
            
        end;
        
        local function
             destroyBuilt(entry)if entry.title then
                 pcall(function
                    ()entry.title.board:Destroy();
                    
                end);
                pcall(function
                    ()entry.title.seat:Destroy();
                    
                end);
                
            end;
            for _, be in ipairs(entry.beams)do
                 pcall(function
                    ()be.beam:Destroy();
                    
                end);
                
            end;
            for _, st in ipairs(entry.stars)do
                 pcall(function
                    ()st.board:Destroy();
                    
                end);
                pcall(function
                    ()st.anchor:Destroy();
                    
                end);
                
            end;
            
        end;
        
        local meteors, nextMeteor={}, 0;
        
        local function
             clearMeteors()for _, m in ipairs(meteors)do
                 pcall(function
                    ()m.beam:Destroy();
                    
                end);
                pcall(function
                    ()m.head:Destroy();
                    
                end);
                pcall(function
                    ()m.tail:Destroy();
                    
                end);
                
            end;
            table.clear(meteors);
            
        end;
        
        local function
             fireMeteor(now)
            local cosY, ang=0.3+math.random()*0.55, math.random()*3.141592653589793*2;
            
            local sinR=math.sqrt(math.max(0, 1-cosY*cosY));
            
            local from=Vector3.new(sinR*math.cos(ang), cosY, sinR*math.sin(ang))*curR;
            dirUnit, vel=from.Unit, Vector3.new(math.random()-0.5, -1.1, math.random()-0.5);
            side=vel-dirUnit*vel:Dot(dirUnit);
            side=if side.Magnitude<0.05 then
                (dirUnit:Cross((Vector3.new(0.0, 1.0, 0.0))))else side;
                headA=Instance.new("Attachment");
                headA.Name=Host.Fw.RandomString();
                headA.Parent=skyAnchor;
                tailA=Instance.new("Attachment");
                tailA.Name=Host.Fw.RandomString();
                tailA.Parent=skyAnchor;
                
                local beam=Instance.new("Beam");
                beam.Attachment0=tailA;
                beam.Attachment1=headA;
                beam.FaceCamera=true;
                beam.LightInfluence=0;
                beam.LightEmission=1;
                beam.Segments=8;
                beam.Width0=0.8;
                beam.Width1=11;
                beam.Parent=skyAnchor;
                meteors[#meteors+1]={beam=beam,head=headA,tail=tailA,from=from,dir=side.Unit,born=now,life=0.9+math.random()*0.8,span=240+math.random()*300,trail=110+math.random()*150};
                
            end;
            
            local function
                 stepMeteors(now, headCol)if not cfg.Meteors then
                     if#meteors>0 then
                         clearMeteors();
                        
                    end;
                    nextMeteor=0;
                    return;
                    
                end;
                
                local ageT=nextMeteor;
                if ageT==0 then
