        for _, assetPath in ipairs(Host.Asset.under("circles/"))do
             fname=string.match(assetPath, "([^/]+)$");
            
            local base, cols, rows, frames=string.match(fname or"", "^(.+)_(%d+)x(%d+)_(%d+)%.png$");
            if base then
                 sname=animAliases[string.lower(base)]or(string.gsub(base, "^%l", string.upper));
                styles[sname]={file=Host.Asset.file(assetPath),cols=tonumber(cols),rows=tonumber(rows),frames=tonumber(frames)};
                styleNames[#styleNames+1]=sname;
                
            end;
            
        end;
        
        local function
             resolveTex(style)if style.asset then
                 return style.asset;
                
            end;
            if style.url~=nil then
                 return style.url or nil;
                
            end;
            style.url=Host.Asset.id(style.file)or false;
            return style.url or nil;
            
        end;
        
        local function
             styleKey(name)name=aliases[name]or name;
            return styles[name]and name or defaultStyle;
            
        end;
        Host.Fw.CircleStyles={Order=styleNames,Styles=styles,Aliases=aliases,Default=defaultStyle};
        task.spawn(function
            ()
            local aliases={};
            for _, sname in ipairs(styleNames)do
                 if not Host.Alive()then
                     return;
                    
                end;
                style=resolveTex(styles[sname]);
                if style then
                     aliases[#aliases+1]=style;
                    
                end;
                task.wait();
                
            end;
            if Host.Alive()and#aliases>0 then
                 Host.Asset.invoke(function
                    ()contentSvc:PreloadAsync(aliases);
                    
                end, 8);
                
            end;
            
        end);
        do
             
            local gunCfg=Host.Fw.GunChams;
            if gunCfg then
                 
                local function
                     makeGunCircle(rec, style)
                    local holder=Instance.new("Part");
                    holder.Name="VisualsGunCircle";
                    holder:SetAttribute(Host.TagKey, Host.TagVal);
                    holder:SetAttribute("VisualsGunAura", true);
                    holder.Anchored=true;
                    holder.CanCollide=false;
                    holder.CanQuery=false;
                    holder.CanTouch=false;
                    holder.CastShadow=false;
                    holder.Transparency=1;
                    holder.Parent=workspace;
                    
                    local anchor=Instance.new("Attachment");
                    anchor.Parent=holder;
                    
                    local emitter=Instance.new("ParticleEmitter");
                    emitter:SetAttribute("VisualsGunAura", true);
                    emitter.Rate=0;
                    emitter.TimeScale=0;
                    emitter.Lifetime, emitter.Speed=NumberRange.new(20), NumberRange.new(0.01);
                    emitter.LightEmission=1;
                    emitter.LightInfluence=0;
                    emitter.LockedToPart=true;
                    emitter.Orientation=Enum.ParticleOrientation.VelocityPerpendicular;
                    emitter.EmissionDirection=Enum.NormalId.Top;
                    emitter.Rotation, emitter.RotSpeed=NumberRange.new(0), NumberRange.new(0);
                    emitter.Parent=anchor;
                    
                    local inst={Part=holder,Emitter=emitter,Style=gunCfg.CircleStyle,Clock=1};
                    rec.Circle=inst;
                    task.defer(function
                        ()
                        local tex=resolveTex(style);
                        if not Host.Alive()or rec.Circle~=inst or not holder.Parent or not tex then
                             return;
                            
                        end;
                        emitter.Texture=tex;
                        local layouts={[2]=Enum.ParticleFlipbookLayout.Grid2x2,[4]=Enum.ParticleFlipbookLayout.Grid4x4,[8]=Enum.ParticleFlipbookLayout.Grid8x8};
                        if style.frames and layouts[style.cols]then
                             emitter.FlipbookLayout=layouts[style.cols];
                            emitter.FlipbookMode=Enum.ParticleFlipbookMode.OneShot;
                            emitter.FlipbookStartRandom=false;
                            emitter.FlipbookFramerate=NumberRange.new(0);
                            
                        end;
                        emitter:Emit(1);
                        inst.Ready=true;
                        
                    end);
                    return inst;
                    
                end;
                Host.Fw.StaticGunCircle=function
                    (rec, style, part, dt)
                    local style, inst=styles[gunCfg.CircleStyle]or styles[defaultStyle], rec.Circle;
                    if not inst or inst.Style~=gunCfg.CircleStyle or not inst.Part.Parent then
                         if inst then
                             inst.Part:Destroy();
                            
                        end;
                        inst=(makeGunCircle(rec, style));
                        
                    end;
                    inst.Clock=inst.Clock+dt;
                    if inst.Clock>=0.1 or inst.Ground~=gunCfg.CircleGround then
                         inst.Clock, inst.Ground=0, gunCfg.CircleGround;
                        local groundPos, groundN=part.Position-Vector3.new(0, part.Size.Y*0.5, 0), Vector3.new(0.0, 1.0, 0.0);
                        if gunCfg.CircleGround then
                             local rayParams=RaycastParams.new();
                            rayParams.FilterType=Enum.RaycastFilterType.Exclude;
                            
                            local ignore={style,inst.Part};
                            for _, pl in ipairs(Host.Players:GetPlayers())do
                                 if pl.Character then
                                     ignore[#ignore+1]=pl.Character;
                                    
                                end;
                                
                            end;
                            rayParams.FilterDescendantsInstances=ignore;
                            rayParams.IgnoreWater=true;
                            local hit=workspace:Raycast(part.Position, Vector3.new(0, -64, 0), rayParams);
                            if hit then
                                 groundPos, groundN=hit.Position, hit.Normal;
                                
                            end;
                            
                        end;
                        inst.Position=groundPos;
                        inst.Normal=groundN;
                        
                    end;
                    local nrm=inst.Normal or(Vector3.new(0.0, 1.0, 0.0));
                    local tangent=nrm:Cross(math.abs(nrm.Y)>0.98 and(Vector3.new(1.0, 0.0, 0.0))or(Vector3.new(0.0, 1.0, 0.0))).Unit;
                    inst.Part.CFrame=CFrame.fromMatrix(inst.Position+nrm*gunCfg.CircleHeight, tangent, nrm, tangent:Cross(nrm).Unit);
                    local em, vals, changed=inst.Emitter, {gunCfg.CircleColor,gunCfg.CircleSize,gunCfg.CircleOpacity,gunCfg.CircleGlow,gunCfg.CircleRotation,gunCfg.CircleThroughWalls}, not inst.Settings;
                    for si, v in ipairs(vals)do
                         changed=if not inst.Settings or v~=inst.Settings[si]then
                             true else changed;
                            
                        end;
                        if changed then
                             inst.Settings=vals;
                            em.Color, em.Size=ColorSequence.new(gunCfg.CircleColor), NumberSequence.new(gunCfg.CircleSize);
                            em.Transparency, em.Brightness=NumberSequence.new(1-gunCfg.CircleOpacity), gunCfg.CircleGlow;
                            em.Rotation=NumberRange.new(gunCfg.CircleRotation);
                            Host.Fx.FxDepth(em, gunCfg.CircleThroughWalls);
                            if inst.Ready then
                                 em:Clear();
                                em:Emit(1);
                                
                            end;
                            
                        end;
                        
                    end;
                    local gunLabel=Host.UI.Guns:AddLabel("Gun Circle");
                    gunLabel:AddToggle({
                        Default=false, Flag="gun_circle", Callback=function
                            (v)gunCfg.Circle=v;
                            gunCfg.SetTracking();
                            
                        end
                    });
                    gunLabel:AddColorPicker({
                        Default=gunCfg.CircleColor, Flag="gun_circle_color", Callback=function
                            (v)gunCfg.CircleColor=v;
                            
                        end
                    });
                    
                    local gunOpts=gunLabel:AddOption(1);
                    gunOpts:AddLabel("Style"):AddDropdown({
                        Default=defaultStyle, Values=styleNames, Flag="gun_circle_style", Callback=function
                            (v)gunCfg.CircleStyle=styleKey(v);
                            
                        end
                    });
                    
                    local sliderSpecs={
                        {"Size","CircleSize","size",5,300,40,10}, {"Opacity","CircleOpacity","opacity",0,100,100,100}, {"Glow","CircleGlow","glow",0,600,200,100}, {"Height","CircleHeight","height",0,200,6,100}, {"Rotation","CircleRotation","rotation",0,360,0,1}
                    };
                    for _, spec in ipairs(sliderSpecs)do
                         
                        local field, div=spec[2], spec[7];
                        gunOpts:AddLabel(spec[1]):AddSlider({
                            Min=spec[4], Max=spec[5], Default=spec[6], Rounding=0, Flag="gun_circle_"..spec[3], Callback=function
                                (v)gunCfg[field]=v/div;
                                
                            end
                        });
                        
                    end;
                    gunOpts:AddLabel("On Ground"):AddToggle({
                        Default=true, Flag="gun_circle_ground", Callback=function
                            (v)gunCfg.CircleGround=v;
                            
                        end
                    });
                    
                end;
                
            end;
            
            local flipLayouts={[2]=Enum.ParticleFlipbookLayout.Grid2x2,[4]=Enum.ParticleFlipbookLayout.Grid4x4,[8]=Enum.ParticleFlipbookLayout.Grid8x8};
            
            local function
                 sampleGround(char, fallbackPos)
                local rayParams=RaycastParams.new();
                rayParams.FilterType=Enum.RaycastFilterType.Exclude;
                rayParams.FilterDescendantsInstances={char};
                rayParams.IgnoreWater=true;
                
                local footNames, posSum, nrmSum, hits={"LeftFoot","RightFoot","Left Leg","Right Leg"}, (Vector3.new(0.0, 0.0, 0.0)), (Vector3.new(0.0, 0.0, 0.0)), 0;
                for _, fname in ipairs(footNames)do
                     local foot=char:FindFirstChild(fname);
                    if foot and(foot:IsA("BasePart"))then
                         local hit=workspace:Raycast(foot.Position+Vector3.new(0, 0.35, 0), Vector3.new(0, -7, 0), rayParams);
                        if hit then
                             posSum, nrmSum, hits=posSum+hit.Position, nrmSum+hit.Normal, hits+1;
                            
                        end;
                        
                    end;
                    
                end;
                if hits>0 then
                     return posSum/hits, nrmSum.Unit;
                    
                end;
                local hit=workspace:Raycast(fallbackPos.Position+Vector3.new(0, 1, 0), Vector3.new(0, -16, 0), rayParams);
                if hit then
                     return hit.Position, hit.Normal;
                    
                end;
                return fallbackPos.Position-Vector3.new(0, 3, 0), (Vector3.new(0.0, 1.0, 0.0));
                
            end;
            
            local liveSet, rings={}, {};
            
            local function
                 releaseTracks()
                local dead={};
                for p in pairs(liveSet)do
                     dead[#dead+1]=p;
                    
                end;
                for _, p in ipairs(dead)do
                     if p.Parent then
                         p:Destroy();
                        
                    end;
                    
                end;
                table.clear(liveSet);
                table.clear(rings);
                
            end;
            
            local function
                 rows(pos, nrmHint)if not Host.Alive()then
                     return;
                    
                end;
                
                local style=styles[cfg.Style]or styles[defaultStyle];
                
                local tex, liveCount, oldestAt, oldest=resolveTex(style), 0, 1/0;
                for p, rec in pairs(rings)do
                     liveCount+=1;
                    if rec.born<oldestAt then
                         oldestAt, oldest=rec.born, p;
                        
                    end;
                    
                end;
                if liveCount>=24 and oldest then
                     oldest:Destroy();
                    
                end;
                local nrm=nrmHint or(Vector3.new(0.0, 1.0, 0.0));
                local tangent=nrm:Cross(math.abs(nrm.Y)>0.98 and(Vector3.new(1.0, 0.0, 0.0))or(Vector3.new(0.0, 1.0, 0.0))).Unit;
                
                local bitan, part=tangent:Cross(nrm).Unit, Instance.new("Part");
                part.Name="VisualsJumpCircle";
                part:SetAttribute(Host.TagKey, Host.TagVal);
                part.Anchored=true;
                part.CanCollide=false;
                part.CanQuery=false;
                part.CanTouch=false;
                part.CastShadow=false;
                part.Transparency=1;
                part.Size=Vector3.new(0.2, 0.2, 0.2);
                part.CFrame=CFrame.fromMatrix(pos+nrm*0.08, tangent, nrm, bitan);
                liveSet[part]=true;
                part.Destroying:Once(function
                    ()liveSet[part]=nil;
                    rings[part]=nil;
                    
                end);
                part.Parent=workspace;
                
                local gui=Instance.new("SurfaceGui");
                gui.Face=Enum.NormalId.Top;
                gui.Adornee=part;
                gui.AlwaysOnTop=false;
                gui.LightInfluence=0;
                gui.CanvasSize=Vector2.new(512, 512);
                gui.Parent=part;
                local ring=Instance.new("Frame");
                ring.BackgroundTransparency, ring.Size=1, UDim2.fromScale(0.94, 0.94);
                ring.Position=UDim2.fromScale(0.03, 0.03);
                ring.BorderSizePixel=0;
                ring.Parent=gui;
                local corner=Instance.new("UICorner");
                corner.CornerRadius=UDim.new(1, 0);
                corner.Parent=ring;
                local stroke=Instance.new("UIStroke");
                stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border;
                stroke.Thickness=7;
                stroke.Color=cfg.Color;
                stroke.Parent=ring;
                rings[part]={born=os.clock(),life=cfg.Life,size=cfg.Size,grow=cfg.Grow/100,bright=math.clamp(cfg.Bright/100,0,1),stroke=stroke,base=part.CFrame,spin=math.rad(cfg.Spin)};
                part.Size=Vector3.new(cfg.Size*0.35, 0.025, cfg.Size*0.35);
                debrisSvc:AddItem(part, cfg.Life+0.4);
                if not tex then
                     return part;
                    
                end;
                if not pcall(function
                    ()
                    local attach=Instance.new("Attachment");
                    attach.Parent=part;
                    
                    local bright, em=math.clamp(cfg.Bright/100, 0, 1), Instance.new("ParticleEmitter");
                    em.Texture=tex;
                    em.Color=ColorSequence.new(cfg.Color);
                    em.LightEmission=1;
                    em.LightInfluence=0;
                    em.Rate=0;
                    em.Lifetime=NumberRange.new(cfg.Life);
                    em.Speed=NumberRange.new(0.01);
                    em.Drag=0;
                    em.Acceleration=Vector3.new(0.0, 0.0, 0.0);
                    em.VelocityInheritance=0;
                    em.EmissionDirection=Enum.NormalId.Top;
                    em.Rotation=NumberRange.new(0);
                    em.RotSpeed=NumberRange.new(cfg.Spin);
                    em.ZOffset=0;
                    pcall(function
                        ()em.Orientation=Enum.ParticleOrientation.VelocityPerpendicular;
                        
                    end);
                    em.Size=NumberSequence.new({NumberSequenceKeypoint.new(0,cfg.Size*0.35),NumberSequenceKeypoint.new(0.4,cfg.Size),NumberSequenceKeypoint.new(1,cfg.Size*cfg.Grow/100)});
                    em.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1-bright),NumberSequenceKeypoint.new(0.6,1-bright*0.55),NumberSequenceKeypoint.new(1,1)});
                    if style.frames and flipLayouts[style.cols]then
                         pcall(function
                            ()em.FlipbookLayout=flipLayouts[style.cols];
                            em.FlipbookMode=Enum.ParticleFlipbookMode.OneShot;
                            
                        end);
                        
                    end;
                    em.Parent=attach;
                    em:Emit(1);
                    gui.Enabled=false;
                    
                end)then
                     for _, child in ipairs(part:GetChildren())do
                         if child:IsA("Attachment")then
                             child:Destroy();
                            
                        end;
                        
                    end;
                    
                end;
                return part;
                
            end;
            
            local function
                 isMine(player)
                local mine=player==Host.LocalPlayer;
                return cfg.Target=="All"or mine and cfg.Target=="Self"or not mine and cfg.Target=="Other";
                
            end;
            
            local recs={};
            
            local function
                 footing(char, hum)
                local root=hum.RootPart or(char:FindFirstChild("HumanoidRootPart"))or char.PrimaryPart;
                return root and(root:IsA("BasePart"))and root or nil;
                
            end;
            
            local function
                 spawnCircle(player, pos, nrm)
                local now=os.clock();
                if player.lastCircleAt and now-player.lastCircleAt<=0.22 and player.lastCirclePosition and(pos-player.lastCirclePosition).Magnitude<=5 then
                     return false;
                    
                end;
                player.lastCircleAt=now;
                player.lastCirclePosition=pos;
                rows(pos, nrm);
                return true;
                
            end;
            
            local function
                 untrackPlayer(player)
                local rec=recs[player];
                if not rec then
                     return;
                    
                end;
                recs[player]=nil;
                for _, c in ipairs(rec.conns)do
                     c:Disconnect();
                    
                end;
                for _, c in ipairs(rec.humanConns or{})do
                     c:Disconnect();
                    
                end;
                
            end;
            
            local function
                 onJump(rec, fromUpdate)
                local root=footing(rec.character, rec.human);
                if not root then
                     return;
                    
                end;
                if fromUpdate and rec.jumpDetected then
                     rec.air=true;
                    return;
                    
                end;
                rec.jumpDetected=true;
                local now=os.clock();
                if cfg.Jump and(isMine(rec.player))and now-rec.lastJump>0.18 then
                     rec.lastJump=now;
                    
                    local pos, nrm=sampleGround(rec.character, root);
                    spawnCircle(rec, pos, nrm);
                    
                end;
                rec.air=true;
                
            end;
            
            local function
                 onLand(rec)if rec.air and cfg.Land and(isMine(rec.player))then
                     
                    local root=footing(rec.character, rec.human);
                    if root then
                         
                        local pos, nrm=sampleGround(rec.character, root);
                        spawnCircle(rec, pos, nrm);
                        
                    end;
                    
                end;
                rec.air=false;
                rec.jumpDetected=false;
                
            end;
            
            local function
                 trackPlayer(player)
                local function
                     hookChar(char)untrackPlayer(player);
                    
                    local rec={
                        player=player, character=char, conns={}, humanConns={}, lastJump=-1/0
                    };
                    recs[player]=rec;
                    
                    local function
                         bindHumanoid(h)if rec.human and rec.human.Parent or not Host.Alive()or recs[player]~=rec or player.Character~=char then
                             return;
                            
                        end;
                        for _, c in ipairs(rec.humanConns)do
                             c:Disconnect();
                            
                        end;
                        table.clear(rec.humanConns);
                        rec.human=h;
                        rec.air=h.FloorMaterial==Enum.Material.Air;
                        rec.floorAir=rec.air;
                        rec.humanConns[#rec.humanConns+1]=h.StateChanged:Connect(function
                            (old, _)if not Host.Alive()or recs[player]~=rec then
                                 return;
                                
                            end;
                            if old==Enum.HumanoidStateType.Jumping then
                                 onJump(rec);
                                elseif old==Enum.HumanoidStateType.Freefall then
                                     rec.air=true;
                                    elseif old==Enum.HumanoidStateType.Landed then
                                         onLand(rec);
                                        
                                    end;
                                    
                                end);
                                rec.humanConns[#rec.humanConns+1]=h.Jumping:Connect(function
                                    (h)if Host.Alive()and h and recs[player]==rec then
                                         onJump(rec);
                                        
                                    end;
                                    
                                end);
                                
                            end;
                            rec.conns[#rec.conns+1]=char.DescendantAdded:Connect(function
                                (desc)if desc:IsA("Humanoid")then
                                     bindHumanoid(desc);
                                    
                                end;
                                
                            end);
                            rec.conns[#rec.conns+1]=char.ChildRemoved:Connect(function
                                (gone)if gone==rec.human then
                                     for _, c in ipairs(rec.humanConns)do
                                         c:Disconnect();
                                        
                                    end;
                                    table.clear(rec.humanConns);
                                    rec.human=nil;
                                    
                                    local h=char:FindFirstChildOfClass("Humanoid");
                                    if h then
                                         bindHumanoid(h);
                                        
                                    end;
                                    
                                end;
                                
                            end);
                            task.spawn(function
                                ()
                                local h=char:FindFirstChildOfClass("Humanoid")or(char:WaitForChild("Humanoid", 10));
                                if h and Host.Alive()and char.Parent and player.Parent and player.Character==char then
                                     bindHumanoid(h);
                                    
                                end;
                                
                            end);
                            
                        end;
                        if player.Character then
                             hookChar(player.Character);
                            
                        end;
                        Host.Fw:AddPlayerSignal(player, player.CharacterAdded:Connect(hookChar));
                        Host.Fw:AddPlayerSignal(player, player.CharacterRemoving:Connect(function
                            ()untrackPlayer(player);
                            
                        end));
                        
                    end;
                    
                    local acc=0;
                    Host.Fw:AddSignal(Host.Run.RenderStepped:Connect(function
                        (dt)if not Host.Alive()then
                             return;
                            
                        end;
                        
                        local now=os.clock();
                        for part, rec in pairs(rings)do
                             
                            local age=(now-rec.born)/rec.life;
                            if age>=1 or not part.Parent then
                                 part:Destroy();
                                else 
                                local sz=rec.size*(age<0.4 and 0.35+age/0.4*0.65 or 1+(rec.grow-1)*(age-0.4)/0.6);
                                part.Size=Vector3.new(sz, 0.025, sz);
                                part.CFrame=rec.base*CFrame.Angles(0, rec.spin*(now-rec.born), 0);
                                rec.stroke.Transparency=1-rec.bright*(1-age)^1.4;
                                
                            end;
                            
                        end;
                        if not(cfg.Jump or cfg.Land)then
                             return;
                            
                        end;
                        acc+=dt;
                        if acc<0.04 then
                             return;
                            
                        end;
                        acc=0;
                        for player, rec in pairs(recs)do
                             local hum, char=rec.human, rec.character;
                            if hum and hum.Parent and char.Parent and player.Character==char and(isMine(player))then
                                 
                                local root=footing(char, hum);
                                if root then
                                     
                                    local airborne=hum.FloorMaterial==Enum.Material.Air;
                                    if airborne and not rec.floorAir and root.AssemblyLinearVelocity.Y>1 then
                                         onJump(rec, true);
                                        elseif not airborne and rec.floorAir then
                                             onLand(rec);
                                            
                                        end;
                                        rec.floorAir=airborne;
                                        
                                    end;
                                    
                                end;
                                
                            end;
                            
                        end));
                        for _, pl in ipairs(Host.Players:GetPlayers())do
                             trackPlayer(pl);
                            
                        end;
                        Host.Fw:AddSignal(Host.Players.PlayerAdded:Connect(trackPlayer));
                        Host.Fw:AddSignal(Host.Players.PlayerRemoving:Connect(untrackPlayer));
                        Host.Fw.Circles=cfg;
                        Host.Fw.SpawnCircle=rows;
                        Host.Fw.ClearCircles=Host.OnUnload("circles", function
                            ()cfg.Jump=false;
                            cfg.Land=false;
                            releaseTracks();
                            for player in pairs(recs)do
                                 untrackPlayer(player);
                                
                            end;
                            table.clear(recs);
                            
                        end);
                        local jumpLabel=Host.UI.Circles:AddLabel("Jump Circle");
                        jumpLabel:AddToggle({
                            Default=false, Flag="jump_circle", Callback=function
                                (v)cfg.Jump=v;
                                if not(cfg.Jump or cfg.Land)then
                                     releaseTracks();
                                    
                                end;
                                
                            end
                        });
                        jumpLabel:AddColorPicker({
                            Default=cfg.Color, Flag="circle_color", Callback=function
                                (v)cfg.Color=v;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Land Circle"):AddToggle({
                            Default=false, Flag="land_circle", Callback=function
                                (v)cfg.Land=v;
                                if not(cfg.Jump or cfg.Land)then
                                     releaseTracks();
                                    
                                end;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Style"):AddDropdown({
                            Default=defaultStyle, Values=styleNames, Flag="circle_style", Callback=function
                                (v)
                                local st=styleKey(v);
                                if cfg.Style~=st then
                                     releaseTracks();
                                    
                                end;
                                cfg.Style=st;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Size"):AddSlider({
                            Min=1, Max=30, Default=4, Rounding=1, Size=100, Flag="circle_size", Callback=function
                                (v)cfg.Size=v;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Life"):AddSlider({
                            Min=2, Max=40, Default=8, Rounding=0, Size=100, Flag="circle_life", Callback=function
                                (v)cfg.Life=v/10;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Grow"):AddSlider({
                            Min=100, Max=400, Default=220, Type="%", Size=100, Flag="circle_grow", Callback=function
                                (v)cfg.Grow=v;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Brightness"):AddSlider({
                            Min=10, Max=100, Default=100, Type="%", Size=100, Flag="circle_bright", Callback=function
                                (v)cfg.Bright=v;
                                
                            end
                        });
                        Host.UI.Circles:AddLabel("Spin"):AddSlider({
                            Min=0, Max=180, Default=0, Rounding=0, Size=100, Flag="circle_spin", Callback=function
                                (v)cfg.Spin=v;
                                
                            end
                        });
