                end));
                collapseBtn.Visible=uiLib.shown==true and not Host.UiLib.Mobile;
                task.defer(layout);
                
                local stale, lastRefresh=false, 0;
                
                local function
                     trackWin()stale, lastRefresh=true, os.clock();
                    
                end;
                Host.UiLib:AddSignal(Host.LocalPlayer.CharacterAdded:Connect(function
                    ()clearModel();
