-- ============ part 4: boot ============
local Host = makeHost()
local win = visualsui:window({})
ui_host.install(Host, visualsui, win)
Host.UiLib.ScreenGui = visualsui.scr
Host.Fw.ScreenGui = Host.Fw.ScreenGui or visualsui.scr
local Salad = { Host = Host, pilots = {} }
local __inits = { initTrails, initGunAuras, initWeather, initBacktrack, initSky, initPlayerAura, initCosmetics, initStarfall, initBloom, initShapes, initChinaHat, initConstellations, initCrosshair, initEmotes, initCircles, initModels, initMotionGraph, initPreview };
for i, p in ipairs({ "trails", "aura", "weather", "backtrack", "sky", "aura2", "cosmetics", "starfall", "bloom", "shapes", "chinahat", "constellations", "crosshair", "emotes", "gallery", "models", "motiongraph", "preview" }) do
  local ok, err = pcall(__inits[i], Host)
  if ok then Salad.pilots[p] = true else warn("[salad] pilot failed " .. p .. ": " .. tostring(err):sub(1, 200)) end
end
function Salad.ClearAll()
  local function sweep(t)
    for k, v in pairs(t) do
      if typeof(v) == "function" and string.sub(tostring(k), 1, 5) == "Clear" then pcall(v) end
    end
  end
  sweep(Host.Store)
  if typeof(Host.Fw) == "table" then sweep(Host.Fw) end
end
return Salad
